using Microsoft.AspNetCore.Mvc; using CarServices.Data; using CarServices.Models; namespace CarServices.Controllers; [ApiController][Route("api/bookings")] public class BookingsController:ControllerBase { readonly AppDbContext db; public BookingsController(AppDbContext d)=>db=d; [HttpGet] public async Task<IActionResult> Get()=>Ok(await db.Bookings.ToListAsync()); [HttpPost] public async Task<IActionResult> Post(Booking b){db.Bookings.Add(b);await db.SaveChangesAsync();return Ok(b);} }
